// The list Telegram suggests when someone types / in a chat with the bot.
// It is what BotFather's /setcommands sets, kept here so it changes along
// with the commands. Everyone gets the first list, a group the commands that
// work there, and each admin the longer list in their own chat. Runs every
// morning, so a new admin gets theirs the next day at the latest; Run now
// does it straight away.
// Jira: DM42-33, DM42-36
const EVERYONE = [
  { command: 'login', description: 'Open the dashboard: a link that works once' },
  { command: 'password', description: 'Choose a password, to log in without Telegram' },
  { command: 'check', description: 'Check all sources now' },
  { command: 'schedule', description: 'See or set when I check the sources' },
  { command: 'reschedule', description: 'Change when I check the sources' },
  { command: 'help', description: 'What I can do' },
];
const ADMINS = [
  ...EVERYONE,
  { command: 'adduser', description: 'An account for the dashboard: /adduser email Name' },
  { command: 'people', description: 'Who can use me and the dashboard' },
  { command: 'remove', description: 'Take someone off the list: /remove Name' },
  { command: 'alerts', description: 'Where I report problems' },
];
// /alerts in a group makes it the place for problem reports.
const GROUPS = [
  { command: 'check', description: 'Check all sources now' },
  { command: 'schedule', description: 'See or set when I check the sources' },
  { command: 'reschedule', description: 'Change when I check the sources' },
  { command: 'alerts', description: 'Report problems in this group (admins)' },
  { command: 'help', description: 'What I can do' },
];

const telegram = (method, body) => this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`,
  body,
  json: true,
});

await telegram('setMyCommands', { commands: EVERYONE });
await telegram('setMyCommands', { commands: GROUPS, scope: { type: 'all_group_chats' } });
let admins = 0;
let others = 0;
let skipped = 0;
for (const { json: person } of $input.all()) {
  if (!person.telegram_user_id) continue;
  const scope = { type: 'chat', chat_id: Number(person.telegram_user_id) };
  try {
    if (person.admin) {
      await telegram('setMyCommands', { commands: ADMINS, scope });
      admins++;
    } else {
      await telegram('deleteMyCommands', { scope });
      others++;
    }
  } catch (e) {
    // Someone who has blocked the bot since. Their chat has no menu to set.
    skipped++;
  }
}
return [{ json: { everyone: EVERYONE.length, admin_chats: admins, other_chats: others, skipped } }];
